PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'manager', "salary_type" varchar not null default 'auto', "salary_amount" numeric, "balance" numeric not null default '0');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "name" varchar not null, "purchase_price" numeric not null, "quantity" integer not null default '0', "manager_id" integer, "created_at" datetime, "updated_at" datetime, "available_in_bot" tinyint(1) not null default '0', "shop_category" varchar, "image_path" varchar, description TEXT NULL, "sale_price" numeric, "quantity_ursynow" integer not null default '0', "quantity_praga" integer not null default '0', foreign key("manager_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "manager_id" integer not null, "amount" numeric not null, "payment_date" date not null, "period_from" date not null, "period_to" date not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("manager_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sale_items" ("id" integer primary key autoincrement not null, "sale_id" integer not null, "product_id" integer not null, "quantity" integer not null, "sale_price" numeric not null, "profit" numeric, "created_at" datetime, "updated_at" datetime, "product_variant_id" integer, "variant_name" varchar, foreign key("sale_id") references "sales"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "shop_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "image_path" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "clients" ("id" integer primary key autoincrement not null, "telegram_user_id" varchar, "telegram_username" varchar, "name" varchar, "phone" varchar, "cashback_balance" numeric not null default '0', "cashback_percent" integer not null default '5', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sales" (id INTEGER NULL PRIMARY KEY AUTOINCREMENT, product_id INTEGER NULL, manager_id INTEGER NOT NULL, quantity INTEGER NOT NULL, sale_price NUMERIC NOT NULL, profit NUMERIC NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, delivery_method varchar NULL, delivery_paczkomat_code varchar NULL, delivery_pickup_name varchar NULL, delivery_pickup_phone varchar NULL, delivery_pickup_district varchar NULL, client_id INTEGER NULL, is_combined tinyint(1) NOT NULL DEFAULT '''0''', profit_to_admin tinyint(1) NOT NULL DEFAULT '''0''', source varchar NOT NULL DEFAULT '''crm''', telegram_user_id varchar NULL, telegram_username varchar NULL, "delivery_pickup_day" varchar, "status" varchar not null default 'accepted');
CREATE TABLE IF NOT EXISTS "product_variants" ("id" integer primary key autoincrement not null, "product_id" integer not null, "name" varchar not null, "quantity" integer not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "quantity_ursynow" integer not null default '0', "quantity_praga" integer not null default '0', foreign key("product_id") references "products"("id") on delete cascade);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "shop_categories_slug_unique" on "shop_categories" ("slug");
CREATE UNIQUE INDEX "clients_telegram_user_id_unique" on "clients" ("telegram_user_id");
COMMIT;
